fn count_and_find_max(v: &Vec<Int>) -> Int {
    let mut count = 0
    let mut max = None
    for x in v {
        if x > 0 {
            count = count + 1
        }
        if letSome(m) == max {
            if x > m {
                max = Some(x)
            }
        } else {
            max = Some(x)
        }
    }
    count + max
}

